import * as fs from 'fs';
import * as path from 'path';
import { App } from 'aws-cdk-lib';
import { localConfig } from './localConfig';
import { LocalHaalCentraalStack } from './LocalHaalCentraalStack';

// Generated by scripts/local.sh deploy
const certificateDir = path.join(__dirname, '../.certs');
if (!fs.existsSync(path.join(certificateDir, 'client.crt'))) {
  throw new Error(`No client certificate in ${certificateDir}, run test/local/scripts/local.sh deploy`);
}
const cert = fs.readFileSync(path.join(certificateDir, 'client.crt'), 'utf-8');

const app = new App();

new LocalHaalCentraalStack(app, 'LocalHaalCentraalStack', {
  env: { account: localConfig.account, region: localConfig.region },
  clientCertificate: {
    key: fs.readFileSync(path.join(certificateDir, 'client.key'), 'utf-8'),
    cert,
    // Self-signed, so the certificate is its own CA
    ca: cert,
  },
});

app.synth();
